/**
 * Screen 05 projection tests for the TUNNEL (2026-11-16, qa/pilot05/proj/tunnel/NOTES.md), same method as the water
 * (`?proj05=1`): the user's APPROVED Screen 05 picture, unwrapped into the tunnel's own coordinates and baked into
 * textures (tools/proj05/tunnel_rings.py + tunnel_bake.py → assets/textures/tunnel05/), so the design is anchored to the
 * 3D tunnel, not pasted over the screen.
 *   `?projwall05=1`  the purple metal WALLS: one texture row per wall bay between two gold rings (AB, BC, CD … as the
 *                    approved picture shows them from the locked 05 camera); u = angle round the tube, v = depth within
 *                    the bay. Bays the picture does not show (in front of ring A, behind the camera) repeat the AB row.
 *   `?projring05=1`  the gold RINGS: the band of the approved ring B unwrapped (u = angle round the ring, v = how far the
 *                    band stands out of the wall), on every 05 ring; the existing far glow still melts the far rings
 *                    into the warm throat.
 * The shader undoes the post chain (grade → sRGB → Neutral tone map → exposure) so the screen shows the approved
 * colours; bloom is measured and fed back into the bake. Default build: none of this runs — the wall and ring
 * materials are wrapped only when a switch is on, every default shader program is unchanged.
 */
import * as THREE from 'three';
import { M05WALL, M05WTILE, PROJ05_INVERSE, m05eye, on05, proj05Pending } from './waterRibbon';
// the tunnel bake follows its own switches OR the master `?match05=1` (on05)
const flag05 = on05;
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';

export const PROJWALL05: boolean = flag05('projwall05');
export const PROJRING05: boolean = flag05('projring05');
/** `?projframe05=1` (2026-11-16): the near gold frame (bottom corners + bottom lip) wears the approved gold band */
export const PROJFRAME05: boolean = flag05('projframe05');
/** `?projlid05=1` (2026-11-16): the approved paddles L1 L2 R1 R2 as Blender-built 3D trays on the real 05 wall */
export const PROJLID05: boolean = flag05('projlid05');
/**
 * `?env05=1` (2026-11-17, washer-environment-modeler, qa/pilot05/full_reference_match/env/NOTES.md): the 05 rings placed
 * where the approved picture shows them from the locked camera (src/world/environment.ts) and the walls / rings baked by
 * CAMERA PROJECTION in their own coordinates (tools/env05/proj_bake.py → assets/textures/env05/): wall atlas with own
 * rows for the near bays (N1, N2), and one ring atlas row per ring (A, B, C … G, N) sampled by (angle round the ring,
 * axial position across the band). Off = every program and texture exactly as before.
 */
export const ENV05: boolean = flag05('env05');

/**
 * The approved paddle is a D-shaped TRAY (studied at 4× zoom: a thick polished gold rim whose INNER face shows above a
 * lavender floor, a thin straight lip along the bottom). Half lathe toward local +X like wallLidGeometry: the D's
 * straight edge lies on local Z (along the tube); the open side faces −Y (the camera / the stream), the closed back +Y
 * (into the wall). Thickness h = tray depth (fraction of the size), centred on its thickness like the wall lids.
 */
export function trayLidGeometry(h: number, segments = 28): THREE.BufferGeometry {
  const prof: [number, number][] = [
    [0, 0.68 * h], [0.78, 0.68 * h], [0.84, 0.62 * h],         // floor (recessed from the open side), fillet
    [0.855, 0.3 * h], [0.865, 0.06 * h], [0.9, 0.0],            // inner rim face down to the lip
    [0.965, 0.0], [1.0, 0.06 * h], [1.025, 0.4 * h],            // rounded lip, outer bulge
    [1.0, 0.85 * h], [0.95, h], [0, h],                          // closed back against the wall
  ];
  const geo = new THREE.LatheGeometry(prof.map(([x, y]) => new THREE.Vector2(x, y)), segments, 0, Math.PI);
  geo.translate(0, -h * 0.5, 0);
  return geo;
}

/**
 * `?projlid05=1` (Blender pipeline, qa/pilot05/proj/tunnel/NOTES.md): the approved picture's four large paddles L1 L2 R1
 * R2 (+ the small far pair L3 R3 on the far wall) as real 3D tray-blocks on the real 05 wall (assets/models/lids05.glb, built in Blender by tools/proj05/lid_blender.py
 * from the approved outlines lifted onto the wall through the locked 05 camera). From the checkpoint their outline is the
 * approved one; riding on, they show their real depth. They carry the approved paddle pixels (camera-projected UVs,
 * assets/textures/tunnel05/lid05.png inside the GLB), shown through the post-chain inverse like the walls. The default
 * paddle pairs and the far slab pucks are left out under the switch.
 */
let lids05Scene: THREE.Object3D | null = null;
// `?env05=1`: the same six paddles lifted onto the DISPLACED env05 wall (scripts/proj05-lid-raycast.mjs --q='<STACK>&env05=1'
// → tools/proj05/lid_blender.py → assets/models/lids05e.glb; qa/pilot05/full_reference_match/env/NOTES.md), else lids05.glb
const lids05Url = ENV05 ? new URL('../../assets/models/lids05e.glb', import.meta.url).href : new URL('../../assets/models/lids05.glb', import.meta.url).href;
const lids05Ready: Promise<void> | null = PROJLID05
  ? new GLTFLoader().loadAsync(lids05Url).then((gltf) => {
    gltf.scene.traverse((o) => {
      const m = o as THREE.Mesh;
      if (!m.isMesh) return;
      const map = (m.material as THREE.MeshStandardMaterial).map;
      if (!map) return;
      map.colorSpace = THREE.NoColorSpace;          // the texels ARE display values: the shader undoes the post chain
      map.needsUpdate = true;
      m.material = lidProjMaterial(map);
      m.frustumCulled = false;
    });
    lids05Scene = gltf.scene;
    lids05Scene.name = 'tube05_lids_blender';
  }).catch((e) => { console.error('[rainbow] projlid05: lids05.glb failed', e); })
  : null;
if (lids05Ready) proj05Pending.push(lids05Ready);

function lidProjMaterial(map: THREE.Texture): THREE.MeshBasicMaterial {
  const mat = new THREE.MeshBasicMaterial({ map, side: THREE.DoubleSide, fog: false });
  mat.onBeforeCompile = (shader) => {
    Object.assign(shader.uniforms, shared);
    shader.fragmentShader = shader.fragmentShader
      .replace('void main() {', `uniform vec4 uPjPost; uniform vec2 uPjRes;
${PROJ05_INVERSE}
void main() {`)
      .replace('#include <dithering_fragment>', `#include <dithering_fragment>
gl_FragColor = vec4(pjInverse(texture2D(map, vMapUv).rgb), 1.0);   // ?projlid05=1: the approved paddle pixels`);
  };
  mat.customProgramCacheKey = () => 'ptlid05';
  mat.onBeforeRender = (renderer) => livePost(renderer);
  return mat;
}

/** the group environment.ts adds under `?projlid05=1`; the Blender paddles join it once the GLB has loaded */
export function lids05Group(): THREE.Group {
  const g = new THREE.Group();
  g.name = 'tube05_lids05';
  const attach = () => { if (lids05Scene) g.add(lids05Scene); };
  if (lids05Scene) attach(); else lids05Ready?.then(attach);
  return g;
}

/** atlas rows of wall05.png (tools/proj05/tunnel_bake.py: ROWS) */
export const PT_ROW = { AB: 0, BC: 1, CD: 2, DE: 3, EF: 4, FG: 5, GX: 6, N1: 7, N2: 8 } as const;
const N_ROWS = ENV05 ? 9 : 7;
/** `?env05=1` ring atlas rows (assets/textures/env05/env05.json: ring.rows) */
export const E5_RING_ROW = { A: 0, B: 1, C: 2, D: 3, E: 4, F: 5, G: 6, N: 7 } as const;
const N_SEG = 8;

const empty = new THREE.DataTexture(new Uint8Array([128, 40, 150, 255]), 1, 1);
empty.needsUpdate = true;

const shared = {
  uPjPost: { value: new THREE.Vector4(0.86, 1.36, 1.15, 0.18) },
  uPjRes: { value: new THREE.Vector2(864, 1536) },
  uPtWall: { value: empty as THREE.Texture },
  uPtWallSize: { value: new THREE.Vector2(1, 1) },
  uPtRows: { value: Array.from({ length: N_ROWS }, () => new THREE.Vector2(0, 1)) },
  uPtRing: { value: empty as THREE.Texture },
  uPtRingSize: { value: new THREE.Vector2(1, 1) },
  uPtFrame: { value: empty as THREE.Texture },
  /** frame05.png: (texture height, band rows NV, left y0, right y0); lip y0 in uPtFrameLip */
  uPtFrameRows: { value: new THREE.Vector4(1, 1, 0, 0) },
  uPtFrameLip: { value: 0 },
  /** `?env05=1`: ring atlas, (texture height, rows height) */
  uE5Ring: { value: empty as THREE.Texture },
  uE5RingSize: { value: new THREE.Vector3(1, 1, 1) },
  /** QA only (scripts/proj05-tunnel-probe.mjs --coords): 1 = write the texture coordinates instead of the colour */
  uPtDbg: { value: 0 },
};
/** QA accessor for the probe script */
export const proj05TunnelShared = shared;

/**
 * `?match05=1&m05far=1` — Screen 05 round 7 (line B, qa/match/05/NOTES.md "Round 7"): the far forced-perspective tunnel
 * of Screen 05 (environment.ts `// ---- 05 far tunnel`, tube.ts ForcedTunnel) recalibrated to the LIVE camera every
 * frame instead of folding away.
 *
 * Why: the far block (rings C … G, the far S-river, the warm throat) is a depth compression along the eye rays of the
 * LOCKED checkpoint eye. From ≈34 u before its seam (sF05) it folded away (`openFor`), so from ≈20 u into the stage the
 * camera saw the far rings / river morphing out and the 06 arch hall behind them — the "old pink default world" of
 * the lead's audit (t66 / t95 frames). The compression is exact for ANY eye position once its two eye-dependent
 * constants (D0 = eye depth of the seam, q = eye offset from the axis) follow the eye, so under this switch:
 *   * the VIRTUAL tunnel (virtual depth Z beyond sF05, tunnel coordinate v = sF05 + u(Z)) stays put — rings, wall rows,
 *     the baked far water F and the far river layout are anchored to it, so everything approaches like real geometry;
 *   * the seam slides ahead of the eye so it never comes nearer than the locked view had it (D0lock ≈ 53 u): the part
 *     of the virtual tunnel between sF05 and the seam is drawn at REAL scale (k = 1) on the same straight axis (it
 *     covers the 05 → 06 flare), capped at `zCap` (just past the 06 start: the 06 river must not climb inside it);
 *   * the far river starts AT the seam (the real ribbon carries the course, coins and Benny before it);
 *   * only at the very end of the stage (eye ≤ ~11 u from the capped seam) the block folds away as before, into 06.
 * Default build and `?match05=1` without `m05far`: this file is never called (environment.ts keeps `openFor`).
 */
import * as THREE from 'three';
import type { ForcedTunnel, TubeWarp } from './tube';
import { tubeCenterAt } from './tube';
import type { FarRiverLayout, FarRiverRow } from './far05';
import type { Course, CourseSample } from './course';
import { EDGE_LIFT, M05BLEND, M05JOIN, MATCH05, ampAt, flag05, m05blend, m05blendTime, m05eye, m05join, m05seam } from '../vfx/waterRibbon';
import { clip05, m05rideS } from '../vfx/clip05';
import type { FarLump05 } from '../vfx/foam';

export const M05FAR: boolean = MATCH05 && flag05('m05far');
/**
 * `&m05end=1` (Screen 05 round 11, needs m05far): the last part of the stage (t ≈ 0.88 … 0.96, Benny ≈ 182 … 186.5)
 * stays inside the painted 05 tunnel. The far block folded away while the eye was still 10 … 6.5 u from its capped
 * seam (s ≈ 186.5), so for the last ≈ 5 u of the stage the camera looked into the old generic 06 hall (white foam
 * walls, flat pink) instead of the 05 rings / slotted walls / S-river. Now it folds only once Benny reaches the seam
 * (eye → seam 6.8 … 5.2 u: Benny ≈ 187.6 … 189, done as Benny enters 06): until then the same world-anchored 05 block (rings, walls, far river,
 * warm throat) continues ahead — faithful continuation of the painted tunnel, nothing new. Geometry, course and the
 * 06 look unchanged; the locked view never uses this (block at its build-time geometry there).
 */
export const M05END: boolean = M05FAR && flag05('m05end');
/**
 * `&m05trans=1` (Screen 05 round 15, needs m05end; qa/match/05/r15/PROGRESS.md step 1): the 05 -> 06 hand-over. With m05end
 * the far block folded while Benny rode the last ≈ 1.3 u of 05 (eye → seam 6.8 … 5.2 u): its rings flew from the
 * compressed tunnel to their real places as small copper hoops floating over the rising 06 crest, its wall swelled into a
 * smeared stack round a flat pink disc (the 06 floor sheet seen through it) and a straight line crossed the water under
 * Benny (t97 / t98). Now the block stays whole — the painted 05 tunnel, gold rings, far river and warm throat — through
 * the whole of 05 and is removed in one step as Benny crosses into 06 (Benny's course position, `m05rideS`), the moment
 * the HUD title turns to 06. From there on everything is exactly as before (the block was already fully folded at the
 * first metres of 06 under m05end), so 06 itself is unchanged. Safety: it still folds if the eye ever comes within
 * 1 u of the seam. Locked view: untouched (atLock path).
 */
export const M05TRANS: boolean = M05END && flag05('m05trans');
/**
 * `&m05fcoin=1` (Screen 05 round 12, needs m05far; src/gameplay/coins.ts): coin LOOK only. Past the far seam the real
 * course climbs away toward 06 while the far block shows the painted 05 river running on into the throat, so the next
 * coins (06) floated over the far block's left wall (t90 / t95). While the block is live, a coin past the seam is drawn
 * where the far block shows that stretch of river: on the far river's cyan core at virtual depth Z = s − sF, scaled like
 * the block (kOf), facing down the tunnel; as the block folds into 06 it moves back to its real place. Positions,
 * pickups, count and score unchanged. `far05Coins` is written by the live sync below.
 */
export const M05FCOIN: boolean = M05FAR && flag05('m05fcoin');
export const far05Coins = {
  /** 1 while the far block is live (not at the locked eye, not fully folded) */
  live: 0,
  /** course s of the sliding seam */
  seamS: 0,
  /** fold factor 0 … 1 */
  open: 1,
  /** `&m05trans=1` (round 16): Benny's course position at which the block is removed (coins.ts: no far look from there) */
  popS: Infinity,
  /** tunnel axis (coins face down it) */
  T: new THREE.Vector3(0, 0, 1),
  /** visual place of a coin at course s, lateral offset dl from the core, height h above the water: writes `out`,
   *  returns the block's scale there (0 = beyond the throat) */
  map: null as null | ((s: number, dl: number, h: number, out: THREE.Vector3) => number),
};

type Item = { u: number; o: THREE.Vector3; basis: THREE.Matrix4; s: THREE.Vector3; openPos: THREE.Vector3; openScale: number };

export interface LiveFar05Args {
  ft: ForcedTunnel;
  farWall: THREE.Mesh;
  farRiver: THREE.Mesh;
  farRings: THREE.InstancedMesh;
  farLids: THREE.InstancedMesh;
  ringItems: Item[];
  lidItems: Item[];
  glow: THREE.Mesh;
  glowMat: THREE.ShaderMaterial;
  lay: FarRiverLayout;
  level: number;
  zEnd: number;
  warp?: TubeWarp;
  /** wall build parameters (as ft.geometry(radial, steps, inset)) */
  radial: number; wallSteps: number; inset: number;
  /** river build parameters (as farRiverGeometry(cols, steps)) */
  cols: number; riverSteps: number;
  /** largest real extension beyond sF05 (units) */
  zCap: number;
  /** fold window: eye → seam distance (units) */
  foldNear: number; foldFar: number;
  /** `&m05trans=1` (round 15): the course position (06 start) where the block is removed in one step */
  popS?: number;
  /** the real course's height above the axis at real distance z beyond sF05 (the far water meets it at the seam) */
  riverUp: (z: number) => number;
  /** `&m05blend=1` (round 9): the real course (the far river's first rows are laid onto the ribbon's surface at the seam) */
  course?: Course;
  /** `&m05fcloud=1` (round 12): foam-cloud lumps along both far banks (src/vfx/foam.ts createFarCloud05) */
  clouds?: { mesh: THREE.InstancedMesh; lumps: FarLump05[] };
}

const ROW_KEYS: (keyof FarRiverRow)[] = ['xB', 'hw', 'cL', 'wL', 'cR', 'wR', 'core'];

/** returns sync(cam): call from every far part's onBeforeRender */
export function createLiveFar05(a: LiveFar05Args): (cam: THREE.Camera) => void {
  const { ft } = a;
  const L = ft.L, c0 = ft.c0, T = ft.T, U = ft.U, Rt = ft.Rt, R = ft.R, sF = ft.sF;
  const D0lock = ft.D0;
  // the river layout depends on Z only: tabulate it once (dense near the seam) and interpolate
  const NT = 2400;
  const tz = new Float64Array(NT + 1), tr = new Float64Array((NT + 1) * ROW_KEYS.length);
  for (let n = 0; n <= NT; n++) {
    const Z = a.zEnd * (n / NT) ** 2;
    tz[n] = Z;
    const r = a.lay.row(Z);
    ROW_KEYS.forEach((k, i) => { tr[n * ROW_KEYS.length + i] = r[k]; });
  }
  const rowAt = (Z: number): FarRiverRow => {
    const f = Math.sqrt(Math.min(1, Math.max(0, Z / a.zEnd))) * NT;
    const n = Math.min(NT - 1, Math.floor(f)), w = f - n;
    const o = {} as FarRiverRow;
    ROW_KEYS.forEach((k, i) => { o[k] = tr[n * ROW_KEYS.length + i] * (1 - w) + tr[(n + 1) * ROW_KEYS.length + i] * w; });
    return o;
  };
  if (M05JOIN) {
    // `&m05join=1` (Screen 05 round 13, waterRibbon.ts M05JOIN): the far layout by virtual depth for the near ribbon's
    // blend band before the seam (the seam never passes zCap) — float, read with manual interpolation (nearest)
    const NJ = 512, zMax = a.zCap + 1;
    const dj = new Float32Array(NJ * 2 * 4);
    for (let n = 0; n < NJ; n++) {
      const Z = (n / (NJ - 1)) * zMax, r = rowAt(Z);

// Screen 05 round 15: layer probe through the 05 -> 06 hand-over (read-only). Same stepping as r8_shots.mjs; at each
// position runs window.__rainbow.probe on a grid (optionally after PRE_JS) and prints the first hits + camera / far state.
//   node tools/match05/r15_probe.mjs "<query>" x97,t98 [port]
import { pathToFileURL } from 'node:url';
import { realpathSync } from 'node:fs';
const { loadPlaywright, CHROMIUM_ARGS } = await import(pathToFileURL(`${process.cwd()}/scripts/lib/pw.mjs`).href);
const [Q = '', ONLY = 'x97', PORT = '5275'] = process.argv.slice(2);
const PRE = process.env.PRE_JS || '';
const EXTRA = process.env.EXTRA_JS || ''; // async expression evaluated after the render (printed)
const GRID = (process.env.GRID || '0,0.6;0,0.3;0,0;0,-0.3;0,-0.6;-0.6,0.3;0.6,0.3;-0.8,-0.3;0.8,-0.3;-0.6,0.7;0.6,0.7').split(';').map((p) => p.split(',').map(Number));
const { chromium } = loadPlaywright();
const { createServer } = await import('vite');
const server = await createServer({ server: { port: Number(PORT), strictPort: false, host: '127.0.0.1', hmr: false, watch: { ignored: ['**/*'] }, fs: { allow: [process.cwd(), realpathSync(`${process.cwd()}/node_modules`)] } }, logLevel: 'error' });
await server.listen();
const url = (server.resolvedUrls?.local?.[0] ?? `http://127.0.0.1:${PORT}/`).replace(/\/$/, '');
const browser = await chromium.launch({ args: CHROMIUM_ARGS });
try {
  const page = await browser.newPage({ viewport: { width: 864, height: 1536 }, deviceScaleFactor: 1 });
  page.on('pageerror', (e) => console.error('pageerror', e.message));
  await page.goto(`${url}/?qa=1&dpr=1${Q ? '&' + Q : ''}`);
  await page.waitForFunction(() => window.__rainbow?.ready === true || window.__error, null, { timeout: 300000 });
  for (const name of ONLY.split(',')) {
    const m = name.match(/^[xt](\d+)([LR]?)/);
    const frac = Number(m[1]) / 100, steer = m[2] === 'L' ? -1 : m[2] === 'R' ? 1 : null;
    const res = await page.evaluate(async ([frac, steer, PRE, GRID, EXTRA]) => {
      const r = window.__rainbow; r.goto('05');
      const s0 = r.state().s, stg = r.course.stage('05');
      const s1 = stg.s1 ?? (stg.s0 + (stg.length ?? 0));
      const target = s0 + frac * (s1 - s0);
      r.setSteer(steer);
      let n = 0; while (r.state().s < target - 1e-3 && n < 4000) { r.step(1); n++; }
      r.setSteer(null);
      r.run(true); await new Promise((res) => requestAnimationFrame(() => requestAnimationFrame(res))); r.run(false);
      if (PRE) { eval(PRE); r.run(true); await new Promise((res) => requestAnimationFrame(() => requestAnimationFrame(res))); r.run(false); }
      const { scene, camera } = r.qa3d();
      let open = null;
      scene.traverse((o) => { if (o.name === 'tube05_far_wall' && o.morphTargetInfluences) open = o.morphTargetInfluences[0]; });
      const cam = camera.position.toArray().map((v) => +v.toFixed(2));
      const hits = GRID.map(([x, y]) => ({ at: [x, y], h: r.probe(x, y).slice(0, 3) }));
      const extra = EXTRA ? await eval(EXTRA) : null;
      return { s: r.state().s, stage: r.state().stage, cam, open, hits, extra };
    }, [frac, steer, PRE, GRID, EXTRA]);
    if (process.env.SHOT_DIR) await page.screenshot({ path: `${process.env.SHOT_DIR}/${name}.png` });
    console.log(`== ${name} s ${res.s} stage ${res.stage} cam ${res.cam} far-open ${res.open} extra ${JSON.stringify(res.extra)}`);
    for (const h of res.hits) console.log('  ', h.at.join(','), h.h.map((x) => `${x.obj} d${x.d}`).join(' | '));
  }
} finally { await browser.close(); await server.close(); }
