    zones.tubes.add(farClouds05.mesh);
  }
  const sync = (cam: THREE.Camera) => {
    const o = ft.openFor(camPos.setFromMatrixPosition(cam.matrixWorld));
    if (Math.abs(o - openNow) < 1e-4) return;
