  farRiver.onBeforeRender = (_r, _s, cam) => { sync(cam); farRiver.morphTargetInfluences![0] = openNow; };
  farRings.onBeforeRender = (_r, _s, cam) => sync(cam);
  farLids.onBeforeRender = (_r, _s, cam) => sync(cam);
