  mat.customProgramCacheKey = () => prevKey() + '|e5ring-' + key;
  const prevRender = mat.onBeforeRender;
  mat.onBeforeRender = (renderer, ...rest) => { livePost(renderer); prevRender.call(mat, renderer, ...rest); };
